-- TU DONG SINH tu entity TypeORM (database/generate-schema.ts). Khong sua tay; sua entity roi chay npm run db:schema.
-- PostgreSQL 13+ : psql -U postgres -d voucher_platform -f database/postgres/schema.sql
-- gen_random_uuid() co san tu PostgreSQL 13 (dong duoi chi can cho ban cu hon)
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

CREATE TYPE "brands_status_enum" AS ENUM('PENDING', 'APPROVED', 'REJECTED');
CREATE TABLE "brands" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "ownerUserId" uuid NOT NULL, "name" character varying NOT NULL, "logo" character varying, "description" text, "categoryId" uuid, "contactInfo" character varying, "bankInfo" character varying, "status" "brands_status_enum" NOT NULL DEFAULT 'PENDING', "rejectReason" character varying, "approvedAt" TIMESTAMP WITH TIME ZONE, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), CONSTRAINT "PK_b0c437120b624da1034a81fc561" PRIMARY KEY ("id"));
CREATE TABLE "campaign_stores" ("campaignId" uuid NOT NULL, "storeId" uuid NOT NULL, CONSTRAINT "PK_488c6863737f7581b7a5712df46" PRIMARY KEY ("campaignId", "storeId"));
CREATE TABLE "categories" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "name" character varying NOT NULL, "icon" character varying, "displayOrder" integer NOT NULL DEFAULT '0', CONSTRAINT "PK_24dbc6126a28ff948da33e97d3b" PRIMARY KEY ("id"));
CREATE TABLE "device_tokens" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "userId" character varying NOT NULL, "token" character varying NOT NULL, "platform" character varying NOT NULL, "lastActiveAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), CONSTRAINT "PK_84700be257607cfb1f9dc2e52c3" PRIMARY KEY ("id"));
CREATE TYPE "favorites_targettype_enum" AS ENUM('BRAND', 'CAMPAIGN');
CREATE TABLE "favorites" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "userId" character varying NOT NULL, "targetType" "favorites_targettype_enum" NOT NULL, "targetId" character varying NOT NULL, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), CONSTRAINT "PK_890818d27523748dd36a4d1bdc8" PRIMARY KEY ("id"));
CREATE TABLE "notifications" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "userId" character varying NOT NULL, "type" character varying NOT NULL, "title" character varying NOT NULL, "body" text NOT NULL, "readAt" boolean NOT NULL DEFAULT false, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), CONSTRAINT "PK_6a72c3c0f683f6462415e653c3a" PRIMARY KEY ("id"));
CREATE TYPE "orders_status_enum" AS ENUM('PENDING', 'PAID', 'CANCELLED', 'FULFILLED', 'REFUNDED_OVERSOLD');
CREATE TABLE "orders" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "userId" uuid NOT NULL, "campaignId" uuid NOT NULL, "quantity" integer NOT NULL, "unitPrice" bigint NOT NULL, "totalAmount" bigint NOT NULL, "status" "orders_status_enum" NOT NULL DEFAULT 'PENDING', "reservedUntil" TIMESTAMP WITH TIME ZONE NOT NULL, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "paidAt" TIMESTAMP WITH TIME ZONE, CONSTRAINT "PK_710e2d4957aa5878dfe94e4ac2f" PRIMARY KEY ("id"));
CREATE TYPE "payments_status_enum" AS ENUM('INITIATED', 'SUCCESS', 'FAILED');
CREATE TABLE "payments" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "orderId" uuid NOT NULL, "gateway" character varying NOT NULL, "gatewayTxnId" character varying NOT NULL, "amount" bigint NOT NULL, "status" "payments_status_enum" NOT NULL DEFAULT 'INITIATED', "rawPayload" jsonb, "receivedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), CONSTRAINT "UQ_8c55510fcf2450a133f0f77fdda" UNIQUE ("gatewayTxnId"), CONSTRAINT "PK_197ab7af18c93fbb0c9b28b4a59" PRIMARY KEY ("id"));
CREATE TABLE "redeem_tokens" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "voucherItemId" uuid NOT NULL, "nonce" character varying NOT NULL, "otpCode" character varying NOT NULL, "issuedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "expiresAt" TIMESTAMP WITH TIME ZONE NOT NULL, "usedAt" TIMESTAMP WITH TIME ZONE, CONSTRAINT "UQ_c3a9d3db15586bac81783574d2e" UNIQUE ("nonce"), CONSTRAINT "PK_32dd539b3a2dfb7c027d23fbf28" PRIMARY KEY ("id"));
CREATE TYPE "redemption_logs_method_enum" AS ENUM('QR', 'OTP');
CREATE TABLE "redemption_logs" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "voucherItemId" uuid NOT NULL, "storeId" uuid NOT NULL, "staffUserId" uuid NOT NULL, "billAmount" bigint, "redeemedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "method" "redemption_logs_method_enum" NOT NULL DEFAULT 'QR', CONSTRAINT "PK_940760ec90aca4edfab73a7e4d3" PRIMARY KEY ("id"));
CREATE TYPE "refund_requests_status_enum" AS ENUM('REQUESTED', 'PROCESSING', 'REJECTED', 'MANUAL_PENDING', 'COMPLETED');
CREATE TABLE "refund_requests" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "voucherItemId" uuid NOT NULL, "userId" uuid NOT NULL, "reason" text, "status" "refund_requests_status_enum" NOT NULL DEFAULT 'REQUESTED', "decidedAt" TIMESTAMP WITH TIME ZONE, "refundTxnId" character varying, "rejectReason" character varying, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), CONSTRAINT "PK_00c88ecd40a63abe92a3dc69897" PRIMARY KEY ("id"));
CREATE TYPE "reviews_status_enum" AS ENUM('VISIBLE', 'HIDDEN');
CREATE TABLE "reviews" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "voucherItemId" uuid NOT NULL, "userId" uuid NOT NULL, "brandId" uuid NOT NULL, "rating" integer NOT NULL, "comment" text, "brandReply" text, "status" "reviews_status_enum" NOT NULL DEFAULT 'VISIBLE', "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), CONSTRAINT "UQ_12c00e8997ab3cc36accda42bb3" UNIQUE ("voucherItemId"), CONSTRAINT "PK_231ae565c273ee700b283f15c1d" PRIMARY KEY ("id"));
CREATE TABLE "settlement_items" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "settlementId" uuid NOT NULL, "orderId" uuid NOT NULL, "amount" bigint NOT NULL, "commissionAmount" bigint NOT NULL, CONSTRAINT "UQ_11a3874c4267e0585e3cd57db90" UNIQUE ("orderId"), CONSTRAINT "PK_0b6ae2a718e28913715e5128a24" PRIMARY KEY ("id"));
CREATE TYPE "settlements_status_enum" AS ENUM('PENDING', 'PAID');
CREATE TABLE "settlements" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "brandId" uuid NOT NULL, "periodStart" TIMESTAMP WITH TIME ZONE NOT NULL, "periodEnd" TIMESTAMP WITH TIME ZONE NOT NULL, "grossRevenue" bigint NOT NULL, "commissionRate" numeric(5,4) NOT NULL, "commissionAmount" bigint NOT NULL, "payableAmount" bigint NOT NULL, "status" "settlements_status_enum" NOT NULL DEFAULT 'PENDING', "paidAt" TIMESTAMP WITH TIME ZONE, "bankTxnRef" character varying, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), CONSTRAINT "PK_5f523ce152b84e818bff9467aab" PRIMARY KEY ("id"));
CREATE TABLE "staff_assignments" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "userId" uuid NOT NULL, "storeId" uuid NOT NULL, "assignedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "active" boolean NOT NULL DEFAULT true, CONSTRAINT "PK_ab013446523a48ceb9b14144530" PRIMARY KEY ("id"));
CREATE TABLE "stores" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "brandId" uuid NOT NULL, "name" character varying NOT NULL, "address" character varying NOT NULL, "latitude" double precision, "longitude" double precision, "phone" character varying, "openingHours" character varying, "status" boolean NOT NULL DEFAULT true, CONSTRAINT "PK_7aa6e7d71fa7acdd7ca43d7c9cb" PRIMARY KEY ("id"));
CREATE TABLE "system_configs" ("key" character varying NOT NULL, "value" text NOT NULL, "updatedBy" character varying, "updatedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), CONSTRAINT "PK_5aff9a6d272a5cedf54d7aaf617" PRIMARY KEY ("key"));
CREATE TYPE "users_role_enum" AS ENUM('GUEST', 'CUSTOMER', 'BRAND_OWNER', 'STORE_STAFF', 'ADMIN');
CREATE TABLE "users" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "email" character varying NOT NULL, "passwordHash" character varying, "fullName" character varying, "phone" character varying, "avatar" character varying, "role" "users_role_enum" NOT NULL DEFAULT 'CUSTOMER', "status" boolean NOT NULL DEFAULT true, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), CONSTRAINT "UQ_97672ac88f789774dd47f7c8be3" UNIQUE ("email"), CONSTRAINT "PK_a3ffb1c0c8416b9fc6f907b7433" PRIMARY KEY ("id"));
CREATE TYPE "voucher_campaigns_vouchertype_enum" AS ENUM('DISCOUNT_CODE', 'PREPAID_VALUE', 'COMBO');
CREATE TYPE "voucher_campaigns_status_enum" AS ENUM('DRAFT', 'PENDING', 'APPROVED', 'PUBLISHED', 'PAUSED', 'ENDED');
CREATE TABLE "voucher_campaigns" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "brandId" uuid NOT NULL, "title" character varying NOT NULL, "image" character varying, "description" text, "terms" text, "voucherType" "voucher_campaigns_vouchertype_enum" NOT NULL, "salePrice" bigint NOT NULL, "faceValue" bigint NOT NULL, "discountPercent" numeric(5,2), "totalQuantity" integer NOT NULL, "soldQuantity" integer NOT NULL DEFAULT '0', "reservedQuantity" integer NOT NULL DEFAULT '0', "limitPerUser" integer NOT NULL DEFAULT '5', "saleStartAt" TIMESTAMP WITH TIME ZONE NOT NULL, "saleEndAt" TIMESTAMP WITH TIME ZONE NOT NULL, "voucherExpireAt" TIMESTAMP WITH TIME ZONE NOT NULL, "status" "voucher_campaigns_status_enum" NOT NULL DEFAULT 'DRAFT', "rejectReason" character varying, "createdAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), CONSTRAINT "PK_9c7d067c7c8883e9d910f5dee6a" PRIMARY KEY ("id"));
CREATE TYPE "voucher_items_status_enum" AS ENUM('ACTIVE', 'USED', 'REFUNDED', 'EXPIRED');
CREATE TABLE "voucher_items" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "orderId" uuid NOT NULL, "campaignId" uuid NOT NULL, "userId" uuid NOT NULL, "code" character varying NOT NULL, "secretKey" character varying NOT NULL, "status" "voucher_items_status_enum" NOT NULL DEFAULT 'ACTIVE', "issuedAt" TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), "usedAt" TIMESTAMP WITH TIME ZONE, "expireAt" TIMESTAMP WITH TIME ZONE NOT NULL, "lockVersion" integer NOT NULL, CONSTRAINT "UQ_78606c39a514b953ab7b8d41061" UNIQUE ("code"), CONSTRAINT "PK_3ef487e14c8f1ebfb1df9edaa3d" PRIMARY KEY ("id"));
